static int close_pair(void *v,fm1_fixed_bridge_access *a){fm1_fixed_runtime *r=v;fm1_fixed_runtime_cert *c=a?a->context:0;if(!r||!c||c->runtime!=r||!c->active)return 0;c->active=0;return fence(r);}
